head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil21210";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil21210.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_currentPageSize_onchange
 * @description slc_currentPageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_currentPageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21210.slc_currentPageSize_onchange' }); }
};

/**
 * @method
 * @name grd_irDataList_oncellclick
 * @description grd_irDataList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_irDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_irDataList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_irDataList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { await scwin.fileDown(r["reoroomId"], r["attachSeq"], r["attachFileChgDdtm"], r["attachFileNm"]); return; } await scwin.searchDetail(r["resoroomId"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_irDataList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_99_onclick
 * @description krxpage_pagenavigator_99 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_99_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_loadListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_99.page' }); } await scwin.tx_load_list(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/company/irData.do?method=searchIRData",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_SearchDetail
 * @description Search Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchDetail = async function () {
    const sbmOptions = {
        id: "tx_fn_SearchDetail",
        method: "post",
        action: "/company/irData.do",
        ref: "dma_SearchDetailReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/company/irData.do?method=searchIRData",
        ref: "dma_loadListReq",
        target: "dlt_entityIrDataAttachVO=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil21210.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] !== null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot !== null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_99").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/common/irDataFileDown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name grd_irDataList_fmt_column8
 * @description grd ir Data List fmt column8 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_irDataList_fmt_column8 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_irDataList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "regStatCd") ?? '') : '');
        if (v === '1') { return "임시저장"; }
        if (v === '2') { return "제출완료"; }
        if (v === '3') { return "승인"; }
        return "미작성";
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_irDataList.column8" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_irDataList_fillAct
 * @description grd ir Data List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_irDataList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_irDataList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_irDataList.fillAct' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_SearchReq').set('method', 'searchIRData');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name searchDetail
 * @description search Detail 처리
 * @param {String} resoroomId resoroomId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function (resoroomId) {
    (document.irDataForm || { elements: [] }).action = '/company/irData.do';
    $c.util.getComponent('dma_SearchReq').set('resoroomId', resoroomId);
    $c.util.getComponent('dma_SearchReq').set('method', 'searchIRDataDetail');
    const nr = await scwin.tx_fn_SearchDetail();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil21211/jldfil21211.xml", { "resoroomId": resoroomId, "method": 'searchIRDataDetail' });
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} resoroomId resoroomId
 * @param {*} attachSeq attachSeq
 * @param {*} attachFileChgDdtm attachFileChgDdtm
 * @param {String} attachFileNm attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (resoroomId, attachSeq, attachFileChgDdtm, attachFileNm) {
    $c.util.getComponent('dma_SearchReq').set('resoroomId', resoroomId);
    $c.util.getComponent('dma_SearchReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_SearchReq').set('attachFileChgDdtm', attachFileChgDdtm);
    $c.util.getComponent('dma_SearchReq').set('attachFileNm', attachFileNm);
    (document.fileDownForm || { elements: [] }).action = '/common/irDataFileDown.do';
    await scwin.tx_fn_FileDown();
};
